jobs=[('۱۴۰۰–۱۴۰۲','کارگروه پایش و ترویج اخلاق حرفه‌ای','سازمان نظام مهندسی استان آذربایجان غربی'),('۱۳۹۲–۱۳۹۳','تدریس نرم‌افزارهای ETABS و AutoCAD','آموزش نرم‌افزارهای مهندسی'),('۱۳۹۰–۱۳۹۱','سرپرست کارگاه','دانشگاه جامع علمی کاربردی بوکان'),('۱۳۹۱–۱۳۹۶','نظارت عالیه','سازمان نظام مهندسی شهرستان بوکان'),('۱۳۸۶–۱۳۹۶','طراح، محاسب و ناظر','پروژه‌های ساختمانی')]
b='<section class="wrap detail section"><span class="kicker">رزومه دانشگاهی و حرفه‌ای</span><h1>یوسف بهرام‌بیگی</h1><p class="lead">Yousef Bahrambeigi · مهندسی عمران ـ سازه</p><button class="button" id="print-resume">چاپ یا ذخیره PDF</button><h2>تحصیلات و زمینه تخصصی</h2><p>دانشجوی دکتری عمران ـ سازه، دانشگاه آزاد اسلامی واحد مهاباد؛ پژوهش در تحلیل سازه، روش اجزای محدود، پاسخ لرزه‌ای و الگوریتم‌های بهینه‌سازی.</p><h2>تجربه حرفه‌ای</h2><div class="timeline">'+''.join(f'<article><span>{y}</span><h3>{t}</h3><p>{s}</p></article>' for y,t,s in jobs)+'</div><h2>مهارت‌ها</h2><p>MATLAB، Python، C++، ANSYS Workbench، Abaqus، تحلیل سازه، FEM و الگوریتم‌های فراابتکاری.</p><h2>انجمن‌های علمی</h2><p>عضویت‌های درج‌شده در رزومه سیویلیکا: انجمن مهندسی عمران ایران، انجمن بتن ایران، انجمن مهندسی سازه ایران، انجمن سازه‌های فضاکار ایران، انجمن سازه‌های فولادی ایران، انجمن مهندسی بتن و سازه‌های بتنی ایران و ASCE. وضعیت جاری عضویت‌ها از مراجع مربوط قابل استعلام است.</p><h2>آثار علمی و نرم‌افزاری</h2><p>فهرست مقالات و پروژه‌های نرم‌افزاری در صفحه اصلی این وب‌سایت به همراه پیوند منبع درج شده است.</p><div class="detail-actions">'+link('/#publications','مقالات','button outline')+link('/#projects','پروژه‌ها','button outline')+link('/assets/resume.jpg','پوستر رزومه دانشگاهی','button outline')+'</div><h2>ارتباط</h2><p dir="ltr">Yousef.Bahrambeigi@iau.ac.ir</p><p>منبع سوابق: '+link(C,'رزومه سیویلیکا')+' · آخرین گردآوری: ۲۶ نوامبر ۲۰۲۶</p></section>'
write('/resume/','رزومه یوسف بهرام‌بیگی | مهندسی عمران و سازه','تحصیلات، سوابق حرفه‌ای، مهارت‌ها، انجمن‌های علمی و نسخه قابل چاپ رزومه یوسف بهرام‌بیگی.',b)
b=f'<section class="wrap detail section"><span class="kicker">شفافیت اطلاعات</span><h1>منابع این وب‌سایت</h1><p class="lead">اطلاعات این سایت از منابع عمومی زیر گردآوری شده است. آخرین بررسی: ۲۶ نوامبر ۲۰۲۶.</p><ul><li>{link(C,"سیویلیکا: رزومه، سوابق و مقالات")}</li><li>{link(G,"گیت‌هاب: مخزن‌ها و مستندات پروژه‌ها")}</li><li>{link(R,"ResearchGate: علایق پژوهشی و آثار علمی")}</li><li>{link("https://y0bahrambeigi.github.io/bhb/resume/","رزومه موجود و تصاویر متعلق به صاحب سایت")}</li><li>{link("https://collaborate.asce.org/waterforum/people/yousef-bahrambeigi","پروفایل ASCE")}</li><li>{link("https://orcid.org/0000-0002-3421-8679","شناسه ORCID درج‌شده در سیویلیکا")}</li></ul><h2>گوگل اسکولار</h2><p>نشانی قطعی پروفایل Google Scholar در زمان گردآوری تأیید نشد. برای جلوگیری از انتساب اشتباه، پروفایل یا آمار استنادی تأییدنشده نمایش داده نشده است.</p><h2>روش ارائه آثار</h2><p>مقاله، ارائه، پیشنهاد پژوهشی و نرم‌افزار انواع متفاوتی از آثار هستند. رکوردهای مشابه سیویلیکا به‌معنای پژوهش‌های منحصربه‌فرد شمرده نشده‌اند. سوابق تاریخی مطابق تاریخ ثبت‌شده در منبع ارائه شده‌اند.</p><h2>حریم خصوصی</h2><p>این نسخه فرم جمع‌آوری اطلاعات، ابزار آمارگیری یا کوکی تبلیغاتی ندارد. پیوندهای خارجی تابع سیاست‌های وب‌سایت مقصد هستند.</p></section>'
write('/sources/','منابع و صحت اطلاعات | یوسف بهرام‌بیگی','منابع رزومه، مقالات و پروژه‌ها و روش بررسی اطلاعات وب‌سایت یوسف بهرام‌بیگی.',b)
eb=f'<section class="wrap detail section" lang="en"><span class="kicker">CIVIL & STRUCTURAL ENGINEERING</span><h1>Yousef<br>Bahrambeigi<span class="accent">.</span></h1><p class="lead">Researcher, educator and civil engineer working across structural analysis, optimization and scientific computing.</p><p>A PhD student in Civil Engineering — Structures at Islamic Azad University, Mahabad. My interests include finite element analysis, metaheuristic optimization, seismic response and interactive engineering education.</p><div class="detail-actions">{link(G,"GitHub projects","button")}{link(C,"Civilica profile","button outline")}{link(R,"ResearchGate","button outline")}</div><h2>Selected projects</h2>'+''.join(f'<article class="paper"><div><h3>{link(repo,name)}</h3><p>{tag}</p></div></article>' for slug,name,title,desc,tag,repo,live,cat in projects)+f'<h2>Contact</h2>{link("mailto:Yousef.Bahrambeigi@iau.ac.ir","Yousef.Bahrambeigi@iau.ac.ir")}<p>{link("/","Explore the full Persian portfolio")}</p></section>'
